const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let workspace=null,sharedRecord=null,accountProfile=null,view='projects',onboardingStep=0,authState='loading';const proposalToken=location.hash.startsWith('#proposal=')?location.hash.slice(10):null;let projects=[],p,preview=false,readonly=!!proposalToken||location.hash.startsWith('#project=');const dialog=$('#dialog');
