function openStage(index){const s=stages(p)[index],state=p.workflow?.states?.[s?.key];if(!s)return;open(s.name,`<span class="stage-owner">${esc(s.owner)}</span><p class="hint">${date(s.start)}${s.start!==s.end?' — '+date(s.end):''}</p>${state?.completedOn?`<p class="stage-state">Completed ${date(state.completedOn)}</p>`:state?.status==='complete-before-tracking'?'<p class="stage-state">Completed before tracking began</p>':''}<div class="stage-detail" style="white-space:pre-line">${esc(s.body)}</div>`,null)}
function render(){if(!readonly&&authState!=='signed-in'){renderAuthState();return}if(!readonly&&accountProfile&&!accountProfile.onboarding_completed_at){renderOnboarding();return}if(!readonly&&(view==='projects'||!p)){renderProjects();return;}if(!readonly&&p.changesPolicy===undefined)p.changesPolicy=defaultChangesPolicy;const client=readonly||preview,s=stages(p),end=s.at(-1).end,progress=currentStageStatus(p);document.title=`${p.title} — Seabird`;$('#actions').innerHTML=readonly?'<button data-action="agreement">Agreement</button>':projectActionsMarkup();
$('#app').innerHTML=`${preview?'<div class="preview-banner">Client preview · your internal pricing is hidden</div>':''}${timelineMarkup(s,end,progress)}<div class="project-heading"><div class="meta"><span>${esc(providerName())} &nbsp; / &nbsp; For ${esc(p.client)}</span><span class="status"><i class="dot"></i>${sharedRecord?(sharedRecord.accepted_at?'Accepted · version '+sharedRecord.version:'Published · version '+sharedRecord.version):readonly?'Project proposal':'Draft proposal'}</span></div><div class="intro"><div><h1>${esc(p.title)}</h1><p>${esc(p.description)}</p></div>${!client?'<button data-action="project">Edit project ↗</button>':''}</div></div>${progressMarkup(progress)}<section class="overview"><div class="scope"><span class="section-label">What we're making</span><h2>${esc(p.description||p.title)}</h2><p>${esc(deliverableItems(p)[0]?.name||'Deliverables to be agreed')}</p><div class="tags"><span class="tag">${p.reviews} review rounds</span><span class="tag">${p.reviewDays} working days per review</span><span class="tag">${date(end)} delivery</span></div></div><div class="price"><span class="section-label">Project fee</span><div class="amount">${money(p.fee)}<small>${p.currency}</small></div><p>${esc(p.tax)} · ${p.deposit}% to get started</p>${!client?'<button class="text-button" data-action="pricing">Work out the price ↗</button>':'<span class="hint">Payment details below ↓</span>'}</div></section><section class="rows">
${row('01','The deliverables','What’s included',deliverableItems(p).map(v=>`<div class="deliverable"><b>${esc(v.name)}</b><p>${esc(v.specs||'Technical specifications to be agreed.')}</p></div>`).join(''),client?'':'scope')}
${row('02','Reviews & timing',`${p.reviews} rounds · ${p.reviewDays} days each`,`<b>${p.reviews} review rounds, with ${p.reviewDays} working days for each.</b>\nOne consolidated set of feedback per round. Dates run Monday–Friday; public holidays are not excluded.\n\n${s.map(v=>`${esc(v.name)}: ${date(v.start)}${v.end!==v.start?' – '+date(v.end):''} · ${esc(v.owner)}`).join('\n')}`,client?'':'schedule')}
${row('03','What we need from you',`By ${date(p.start)}`,`<b>${esc(p.client)} to supply by kick-off:</b>\n${esc(p.inputs)}`,client?'':'inputs')}
${row('04','Payments',`${p.deposit}% now · ${100-p.deposit}% at delivery`,`<div class="payment"><span><b>01 &nbsp; To book the project</b><br>${date(p.start)} · ${p.deposit}%</span><b>${money(Math.round(p.fee*p.deposit/100))}</b></div><div class="payment"><span><b>02 &nbsp; Before final delivery</b><br>${date(end)} · ${100-p.deposit}%</span><b>${money(p.fee-Math.round(p.fee*p.deposit/100))}</b></div><p>${esc(p.paymentNote)}</p>`,client?'':'payments')}
${row('05','The working agreement','The small, important things',`${esc(p.terms)}\n\n<b>Usage & handover</b>\n${esc(p.rights)}`,client?'':'terms')}
${row('06','Changes & delays','When the plan changes',esc(p.changesPolicy??'No separate changes policy was specified in this version. Please refer to the working agreement.'),client?'':'changes')}</section><div class="bottom-note"><span class="asterisk">✳</span><span>${sharedRecord?'Review all details, then record your acceptance below.':readonly?`This is a proposal snapshot. Please confirm the scope, dates and terms with ${esc(providerName())} before work begins.`:'Everything in one place. Open a card to fine-tune the details, then preview what your client sees.'}</span></div>`;
$('.timeline')?.querySelectorAll('.stage').forEach((stage,index)=>stage.style.setProperty('--stage-weight',String(Math.max(1,(Date.parse(s[index].end)-Date.parse(s[index].start))/86400000))));
$('.timeline-labels')?.querySelectorAll('.timeline-label').forEach((label,index)=>label.style.setProperty('--stage-weight',String(Math.max(1,(Date.parse(s[index].end)-Date.parse(s[index].start))/86400000))));
$('.timeline-scroll')?.insertAdjacentHTML('afterbegin',timelineToday(s,end));
if(sharedRecord)$('#app').append(acceptancePanel({cloud:createCloud(),token:proposalToken,record:sharedRecord,reload:reloadPublished}));}
function row(n,title,summary,body,edit){
const descriptions={'01':'The items we will deliver, and their technical specifications.','02':'When we make, when you review, and when it is ready.','03':'The files and information we need to get started.','04':'How much is due, and when to pay it.','05':'Scope, usage and the terms we agree to.','06':'How we handle changes, moving dates and late inputs.'};
const icons={'01':'▤','02':'◷','03':'↓','04':'$','05':'≡','06':'↔'};
return `<details class="project-card" name="project-sections"><summary><span class="card-top"><span class="card-icon" aria-hidden="true">${icons[n]}</span><span class="num">${n}</span></span><span class="row-title">${title}</span><span class="card-description">${descriptions[n]}</span><span class="card-bottom"><span class="row-summary">${summary}</span><span class="plus">+</span></span></summary><div class="detail">${body}${edit?`<br><button data-action="${edit}">Edit details ↗</button>`:''}</div></details>`}
const field=(name,label,type='text',value=p[name],attrs='')=>`<label for="${name}">${label}</label>${type==='textarea'?`<textarea id="${name}" name="${name}" maxlength="10000">${esc(value)}</textarea>`:`<input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs} required>`}`;
const num=(name,label,min=0,max=1000000)=>field(name,label,'number',p[name],`min="${min}" max="${max}" step="${['reviews','conceptDays','animationDays','reviewDays','finishDays'].includes(name)?1:0.01}"`);
function open(title,html,onSubmit,button='Save changes ↗'){ $('#dialog-title').textContent=title;$('#fields').innerHTML=html;$('#submit').textContent=button;$('#submit').hidden=!onSubmit;$('#form').onsubmit=e=>{e.preventDefault();if(onSubmit)onSubmit(new FormData(e.target))};dialog.showModal()}
 function edit(kind){if(kind==='scope'){editDeliverables();return}if(kind==='schedule'&&p.workflow&&(p.workflow.activity.some(item=>item.type!=='tracking_started')||Object.values(p.workflow.states).some(state=>state.status!=='incomplete')||todayInTimeZone(p.workflow.timeZone)>=p.start)){openReplan();return}let html='',title='';switch(kind){case'project':title='The project';html=field('title','Project name','text',p.title,'maxlength="200"')+field('client','Client','text',p.client,'maxlength="200"')+field('description','One-line description');break;case'scope':title='What’s included';html=field('deliverables','Deliverables · one per line','textarea');break;case'inputs':title='What the client supplies';html=field('inputs','Materials due at kick-off · one per line','textarea');break;case'changes':title='Changes & delays';html=field('changesPolicy','How we handle changes and delays','textarea');break;case'terms':title='The working agreement';html=field('terms','Commercial terms','textarea')+field('rights','Usage, licences & source files','textarea');break;case'payments':title='When you get paid';html=num('deposit','Deposit (%)',0,100)+field('paymentNote','Payment terms','textarea')+field('tax','Tax wording');break;case'schedule':title='Make room for good work';html=field('start','Kick-off date','date')+'<div class="pair"><div>'+num('conceptDays','Direction (working days)',1,90)+'</div><div>'+num('animationDays',(p.makingStageName||'Making')+' (working days)',1,90)+'</div></div><div class="pair"><div>'+num('reviews','Review rounds',1,6)+'</div><div>'+num('reviewDays','Days for each review',1,90)+'</div></div>'+num('finishDays','Refinement / delivery days',1,90)+'<p class="hint">Changing a duration moves later stages automatically. Weekends are skipped; public holidays are not.</p>';break;case'pricing':title='A price that adds up';html='<p class="hint">Only you see the working numbers. Your client sees the agreed project fee.</p><div class="pair"><div>'+num('rate','Day rate')+'</div><div>'+num('days','Estimated days',0.5,1000)+'</div></div>'+num('costs','Other costs')+'<div class="calc"><span>Working estimate</span><b id="estimate"></b></div>'+num('fee','Agreed project fee')+'<label for="currency">Currency</label><select id="currency" name="currency">'+['NZD','USD','AUD','GBP','EUR'].map(c=>`<option ${p.currency===c?'selected':''}>${c}</option>`).join('')+'</select>'+field('tax','Tax wording');break}
open(title,html,data=>{const next={...p};for(const[k,v]of data)next[k]=['rate','days','costs','fee','deposit','reviews','conceptDays','animationDays','reviewDays','finishDays'].includes(k)?Number(v):v.trim();if(!next.title||!next.client||!validate(next)){toast('Please check your project details.');return}Object.assign(p,next);if(kind==='schedule'&&p.workflow)refreshUnstartedPlan(p);save();dialog.close();toast('Project updated')});if(kind==='pricing'){const update=()=>$('#estimate').textContent=money(Number($('#rate').value)*Number($('#days').value)+Number($('#costs').value));['rate','days','costs'].forEach(k=>$('#'+k).addEventListener('input',update));update()}}

function openTracking(){
 const plan=stages(p);open('Where are you up to?','<p class="hint">Choose the first stage that is not complete. Earlier stages will be recorded as complete before tracking began, without inventing completion dates.</p><label for="currentStageKey">Current stage</label><select id="currentStageKey" name="currentStageKey">'+plan.map(stage=>`<option value="${esc(stage.key)}">${esc(stage.name)} · ${date(stage.start)}</option>`).join('')+'</select>',data=>{startTracking(p,{currentStageKey:data.get('currentStageKey')});save();dialog.close();toast('Project tracking started.');},'Start tracking ↗');
}
function openWaiting(){
 const status=currentStageStatus(p);if(!status.current)return;
 open('What are we waiting on?','<p class="hint">Waiting explains the delay but does not move the agreed dates. Use Change plan when the schedule needs to move.</p><label for="party">Waiting on</label><select id="party" name="party"><option value="client">Client</option><option value="studio">Studio</option><option value="shared">Both of us</option><option value="third-party">Third party</option></select><label for="reason">Note (optional)</label><textarea id="reason" name="reason" maxlength="1000" placeholder="Feedback, source files, approval, availability…"></textarea>',data=>{setStageWaiting(p,status.current.key,data.get('party'),data.get('reason'));save();dialog.close();toast('Waiting state recorded.');},'Record waiting ↗');
}
function openReplan(){
 const status=currentStageStatus(p);if(!status.current){toast('This project is complete.');return;}
 open('Change the remaining plan','<p class="hint">Extend or shorten the current stage and move every incomplete stage after it by the same number of working days. Completed stages and accepted versions stay unchanged.</p><div class="replan-summary"><b>'+esc(status.current.name)+'</b><span>Currently due '+date(status.current.end)+'</span></div><label for="workingDays">Move by working days</label><input id="workingDays" name="workingDays" type="number" min="-3650" max="3650" step="1" value="'+(status.days<0?Math.abs(status.days):1)+'" required><label for="party">Reason belongs to</label><select id="party" name="party"><option value="client">Client</option><option value="studio">Studio</option><option value="shared" selected>Shared / agreed</option><option value="third-party">Third party</option></select><label for="reason">Reason</label><textarea id="reason" name="reason" maxlength="1000" required placeholder="Why the plan is moving"></textarea>',data=>{const days=Number(data.get('workingDays'));if(!Number.isInteger(days)||days===0){toast('Enter a non-zero number of working days.');return}shiftRemainingStages(p,status.current.key,days,{party:data.get('party'),reason:data.get('reason')});save();dialog.close();toast('Working plan updated. Publish a new version when the client should agree to it.');},'Update working plan ↗');
}
function openVariation(){
 open('Change the project','<p class="hint">A formal variation can change the scope, price, terms or schedule. It remains private until you deliberately publish a new client version.</p><label for="area">What needs to change?</label><select id="area" name="area"><option value="scope">Deliverables</option><option value="pricing">Price</option><option value="terms">Terms and rights</option><option value="payments">Payment terms</option><option value="schedule">Schedule</option><option value="changes">Changes policy</option></select><label for="reason">Why is it changing?</label><textarea id="reason" name="reason" maxlength="900" required></textarea>',data=>{const area=data.get('area');recordVariation(p,area,data.get('reason'));save();dialog.close();edit(area);},'Continue to changes ↗');
}
function activityText(item){
 const stage=stages(p).find(value=>value.key===item.stageKey)?.name??'Project';
 if(item.type==='tracking_started')return`Tracking started at ${stage}`;
 if(item.type==='stage_completed')return`${stage} completed`;
 if(item.type==='waiting_started')return`${stage} waiting on ${item.party}${item.reason?' · '+item.reason:''}`;
 if(item.type==='waiting_cleared')return`${stage} no longer waiting`;
 if(item.type==='schedule_shifted')return`${stage} and the remaining plan moved ${item.workingDays>0?'+':''}${item.workingDays} working days${item.reason?' · '+item.reason:''}`;
 if(item.type==='variation_started')return`Project change started · ${item.reason}`;
 if(item.type==='variation_published')return item.reason;
 return item.type;
}
function openActivity(){
 if(!p.workflow){openTracking();return}const items=[...p.workflow.activity].reverse();open('Project activity',items.length?'<div class="activity-list">'+items.map(item=>`<div><span>${date(item.on)}</span><p>${esc(activityText(item))}</p></div>`).join('')+'</div>':'<p class="hint">No activity yet.</p>',null);
}
function finishCurrentStage(){
 const before=currentStageStatus(p);if(!before.current)return;completeStage(p,before.current.key);save();const next=currentStageStatus(p);toast(`${before.current.name} completed.`);
 if(next.state==='overdue'){
  open('The next stage is already late',`<p>${esc(next.current.name)} is ${Math.abs(next.days)} working day${Math.abs(next.days)===1?'':'s'} overdue.</p><p class="hint">Keep the existing dates, or deliberately move the remaining plan. Nothing changes automatically.</p><div class="choice-buttons"><button type="button" id="keep-plan">Keep dates</button><button type="button" class="primary" id="move-plan">Move remaining plan</button></div>`,null);
  $('#keep-plan').onclick=()=>dialog.close();$('#move-plan').onclick=()=>{dialog.close();openReplan()};
 }
}
function download(name,data){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function share(){shareProject({workspace,project:p,open,toast,download,onPublished:async result=>{recordVariationPublished(p,result.version);save();await workspace.save();}}).catch(error=>toast(error.message));}
function projectList(){view='projects';preview=false;if(dialog.open)dialog.close();render();window.scrollTo(0,0);}
function projectTile(item,i){const progress=currentStageStatus(item),progressText=progress.tracking?(progress.state==='complete'?'Complete':`${progress.current?.name??'Project'} · ${progress.label}`):'Tracking not started';return'<button class="project-tile" data-project="'+i+'"><span class="project-tile-main"><span class="project-client">'+esc(item.client)+'</span><span class="project-title">'+esc(item.title)+'</span><span class="project-description">'+esc(item.description||'Scope, schedule and agreement')+'</span></span><span class="project-tile-side"><span class="project-progress is-'+esc(progress.state||'setup')+'">'+esc(progressText)+'</span><span class="project-tile-meta"><span>'+new Intl.NumberFormat('en-NZ',{style:'currency',currency:item.currency,maximumFractionDigits:0}).format(item.fee)+' '+item.currency+'</span><span>Kick-off '+date(item.start)+'</span></span><span class="project-open">Open project ↗</span></span></button>'}
function renderAuthState(){
 document.title='Seabird';$('#actions').innerHTML='';
 $('#app').innerHTML=authState==='loading'?'<section class="auth-home is-loading" aria-busy="true"><p>Loading Seabird…</p></section>':'<section class="auth-home"><h1>Sign in to Seabird</h1><button class="primary google-signin" data-action="sign-in"><span aria-hidden="true">G</span>Continue with Google</button></section>';
}
function renderProjects(){
 document.title='Your projects — Seabird';
 $('#actions').innerHTML='<button class="primary" data-action="new">+ New project</button>';
 $('#app').innerHTML='<section class="projects-home">'+(projects.length?'<div class="project-grid">'+projects.map(projectTile).join('')+'</div>':'<div class="projects-empty"><h1>No projects yet</h1><button class="primary" data-action="new">Create a project</button></div>')+'</section>';
}
function createProject(){
 if(!workspace?.cloud.user){workspace?.focus();toast('Sign in to create a project.');return;}
 const today=new Date();const start=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');
 open('A new project',field('title','Project name','text','','maxlength="200"')+field('client','Client','text','','maxlength="200"')+field('description','A short description','textarea','')+field('start','Kick-off date','date',start)+'<p class="hint">Start with the basics. Add the fee, deliverables and terms inside your project.</p>',async data=>{
  try{const next=newProject(Object.fromEntries(data),{defaults:accountProfile?.project_defaults,provider:accountProfile});projects.unshift(next);p=next;view='project';save();dialog.close();await workspace.save();toast('Project created.');}catch(e){toast(e.message);}
 },'Create project ↗');
}

document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.stage!==undefined){openStage(Number(button.dataset.stage));return}if(button.dataset.project!==undefined&&!readonly){p=projects[Number(button.dataset.project)];view='project';preview=false;if(dialog.open)dialog.close();render();window.scrollTo(0,0);return}const a=button.dataset.action;if(a==='agreement'){showAgreement();return}if(a==='back-project'){closeAgreement();return}if(a==='download-agreement'){downloadAgreement();return}if(readonly)return;if(a==='sign-in')workspace?.signInWithGoogle();else if(a==='start-tracking')openTracking();else if(a==='complete-stage')finishCurrentStage();else if(a==='waiting')openWaiting();else if(a==='clear-waiting'){const status=currentStageStatus(p);clearStageWaiting(p,status.current.key);save();toast('Waiting state cleared.')}else if(a==='replan')openReplan();else if(a==='variation')openVariation();else if(a==='activity')openActivity();else if(a==='preview'){preview=!preview;render()}else if(a==='share')share();else if(a==='projects')projectList();else if(a==='new')createProject();else if(a==='export')download('seabird-projects-backup.json',JSON.stringify(projects,null,2));else if(a==='import'){const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{const file=input.files[0];if(file.size>2000000)throw Error();const items=JSON.parse(await file.text());if(!Array.isArray(items)||!items.length||items.length>100||!items.every(validate))throw Error();for(const item of items){projects.push({...item,id:crypto.randomUUID(),rate:Number(item.rate)||0,days:Number(item.days)||1,costs:Number(item.costs)||0})}view='projects';save();if(dialog.open)dialog.close();toast('Backup imported')}catch{toast('This file is not a valid Seabird project backup.')}};input.click()}else if(a)edit(a)});
document.addEventListener('change',e=>{if(e.target.id==='timeline-stage-select'&&e.target.value!==''){openStage(Number(e.target.value));e.target.value=''}});
$('#close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});window.addEventListener('hashchange',()=>location.reload());render();if(!readonly)save();

function editDeliverables(){
  const itemFields=(v)=>'<div class="deliverable-editor"><label>Item name<input class="item-name" maxlength="200" required value="'+esc(v.name)+'" placeholder="Opening title sequence — 4K master"></label><label>Technical specifications<textarea class="item-specs" maxlength="2000" placeholder="Resolution, frame rate, pixel aspect, codec / compression, colour space…">'+esc(v.specs)+'</textarea></label><button type="button" class="remove-deliverable">Remove item</button></div>';
  open('The deliverables','<p class="hint">Name each item, then add its delivery specifications. For video: square pixels, 4:2:2, Rec.709, plus resolution, frame rate and codec as needed.</p><div id="deliverable-editors">'+deliverableItems(p).map(itemFields).join('')+'</div><button type="button" id="add-deliverable">+ Add item</button>',()=>{
    const items=Array.from(document.querySelectorAll('.deliverable-editor'),el=>({name:el.querySelector('.item-name').value.trim(),specs:el.querySelector('.item-specs').value.trim()}));
    const next={...p,deliverableItems:items,deliverables:items.map(v=>v.name).join('\n')};
    if(!validate(next)){toast('Add at least one named deliverable, up to 30 items.');return}
    Object.assign(p,next);save();dialog.close();toast('Deliverables updated');
  });
  $('#add-deliverable').onclick=()=>{if(document.querySelectorAll('.deliverable-editor').length>=30){toast('You can add up to 30 items.');return}$('#deliverable-editors').insertAdjacentHTML('beforeend',itemFields({name:'',specs:''}));$('#deliverable-editors').lastElementChild.querySelector('input').focus()};
  $('#deliverable-editors').onclick=e=>{if(e.target.closest('.remove-deliverable'))e.target.closest('.deliverable-editor').remove()};
}


let agreementRequest=0,agreementSnapshot=null,agreementIssued=null;
function showAgreement(){
 agreementRequest++;agreementSnapshot=structuredClone(p);if(!readonly){const identity=providerIdentity(accountProfile);if(identity)agreementSnapshot.provider=identity}agreementIssued=sharedRecord?new Date(sharedRecord.published_at):new Date();
 $('#actions').innerHTML='<button data-action="back-project">← Back to project</button><button class="primary" data-action="download-agreement">Download PDF ↓</button>';
 $('#app').innerHTML='<section class="agreement-view"><div class="agreement-intro"><span class="section-label">THE COMPLETE PICTURE</span><h1>Your project, on paper.</h1><p>Review the full agreement below. Download a PDF when you are ready to email it for signing.</p><p class="hint">The PDF uses the same content and styling, with page breaks for printing.</p></div>'+agreementHtml(agreementSnapshot,agreementIssued)+'</section>';
 window.scrollTo(0,0);
}
function closeAgreement(){agreementRequest++;agreementSnapshot=null;render();window.scrollTo(0,0)}
async function downloadAgreement(){
 if(!agreementSnapshot)return;const request=agreementRequest,button=$('[data-action="download-agreement"]');if(button.disabled)return;
 button.disabled=true;button.textContent='Making PDF…';
 try{const snapshot=agreementSnapshot;const blob=await agreementBlob(snapshot,agreementIssued);if(request!==agreementRequest)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(snapshot.title.replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'')||'project')+'-agreement.pdf';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
 catch{if(request===agreementRequest)toast('Could not generate the PDF. Please try again.')}
 finally{if(request===agreementRequest){button.disabled=false;button.textContent='Download PDF ↓'}}
}
document.addEventListener('toggle',e=>{if(e.target.matches('.project-card')&&e.target.open)document.querySelectorAll('.project-card').forEach(card=>{if(card!==e.target)card.open=false})},true);

if(!readonly)workspace=mountCloud({getProjects:()=>projects,setAccount,setProfile,validate,onError:toast,setProjects:items=>{projects=items;p=projects[0];authState='signed-in';save();}});
